#include <vector>
#include <queue>
#include <unordered_map>

class Solution {
public:
    int minJumps(std::vector<int>& arr) {
        int n = arr.size();
        if (n <= 1) return 0;
        std::unordered_map<int, std::vector<int>> graph;
        for (int i = 0; i < n; ++i) graph[arr[i]].push_back(i);
        std::queue<std::pair<int, int>> q;
        q.push({0, 0});
        std::vector<bool> visited(n, false);
        visited[0] = true;
        while (!q.empty()) {
            auto [i, steps] = q.front();
            q.pop();
            if (i == n - 1) return steps;
            std::vector<int> nxts;
            if (i - 1 >= 0) nxts.push_back(i - 1);
            if (i + 1 < n) nxts.push_back(i + 1);
            if (graph.find(arr[i]) != graph.end()) {
                for (int idx : graph[arr[i]]) {
                    if (idx != i) nxts.push_back(idx);
                }
                graph.erase(arr[i]);
            }
            for (int nxt : nxts) {
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    q.push({nxt, steps + 1});
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minJumps(int[] arr) {
        int n = arr.length;
        if (n <= 1) return 0;
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0});
        boolean[] visited = new boolean[n];
        visited[0] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int i = cur[0], steps = cur[1];
            if (i == n - 1) return steps;
            List<Integer> nxts = new ArrayList<>();
            if (i - 1 >= 0) nxts.add(i - 1);
            if (i + 1 < n) nxts.add(i + 1);
            if (graph.containsKey(arr[i])) {
                nxts.addAll(graph.get(arr[i]));
                graph.remove(arr[i]);
            }
            for (int nxt : nxts) {
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    q.offer(new int[]{nxt, steps + 1});
                }
            }
        }
        return -1;
    }
}

var minJumps = function(arr) {
    const n = arr.length;
    if (n <= 1) return 0;
    const graph = new Map();
    for (let i = 0; i < n; i++) {
        if (!graph.has(arr[i])) graph.set(arr[i], []);
        graph.get(arr[i]).push(i);
    }
    const q = [[0, 0]];
    const visited = new Uint8Array(n);
    visited[0] = 1;
    let head = 0;
    while (head < q.length) {
        const [i, steps] = q[head++];
        if (i === n - 1) return steps;
        const nxts = [];
        if (i - 1 >= 0) nxts.push(i - 1);
        if (i + 1 < n) nxts.push(i + 1);
        if (graph.has(arr[i])) {
            for (const idx of graph.get(arr[i])) {
                if (idx !== i) nxts.push(idx);
            }
            graph.delete(arr[i]);
        }
        for (const nxt of nxts) {
            if (!visited[nxt]) {
                visited[nxt] = 1;
                q.push([nxt, steps + 1]);
            }
        }
    }
    return -1;
};
